inv_c3f3f263	fisherman	Is it safe to fish offshore Karnataka today? Assess 24h wave, wind, and harbour conditions.	partial	{"plan_id": "plan_b77a303b", "workspace": "fisherman", "query": "Is it safe to fish offshore Karnataka today? Assess 24h wave, wind, and harbour conditions.", "normalized_intent": "fisherman_general_inquiry", "target_coordinates": {"latitude": 13.5, "longitude": 74.5, "radius_km": 150.0}, "target_time_horizon": "7-day numerical forecast + historical baseline", "steps": [{"step_id": "step_ocean_research", "agent_id": "ocean_research", "agent_name": "Ocean Intelligence & Research Agent", "phase": "specialist_concurrent", "dependencies": [], "description": "Analyze physical SST, thermal anomalies, currents, and biochemical chlorophyll-a spectra.", "timeout_seconds": 20.0, "max_retries": 2}, {"step_id": "step_marine_hazard", "agent_id": "marine_hazard", "agent_name": "Marine Hazard & Forecast Agent", "phase": "specialist_concurrent", "dependencies": [], "description": "Ingest storm track, Douglas sea state wave spectra, and meteorological alerts.", "timeout_seconds": 20.0, "max_retries": 2}, {"step_id": "step_coastal_risk", "agent_id": "coastal_risk", "agent_name": "Coastal Impact & Risk Agent", "phase": "specialist_dependent", "dependencies": ["step_marine_hazard"], "description": "Evaluate coastal settlement and population exposure using upstream hazard wave and surge parameters.", "timeout_seconds": 20.0, "max_retries": 2}, {"step_id": "step_evidence_verification", "agent_id": "evidence_verification", "agent_name": "Evidence & Scientific Verification Agent", "phase": "scientific_auditor", "dependencies": ["step_ocean_research", "step_marine_hazard", "step_coastal_risk"], "description": "Independently verify scientific claims, cryptographic SHA-256 evidence integrity, units, and detect cross-source conflicts.", "timeout_seconds": 25.0, "max_retries": 1}], "selected_agents": ["coastal_risk", "ocean_research", "marine_hazard", "evidence_verification